tool_input.command:
mkdir -p components/ui/badge && printf "export * from './badge';\n" > components/ui/badge/index.ts && cat > components/ui/badge/badge.tsx <<'EOF'
import * as React from 'react';

import { cn } from '@/utils/cn';

export type BadgeProps = React.HTMLAttributes<HTMLSpanElement>;

export const Badge = ({ className, ...props }: BadgeProps) => {
  return (
    <span
      className={cn(
        'ml-2 inline-flex items-center rounded-full border border-indigo-200 bg-indigo-50 px-2 py-0.5 text-xs font-semibold text-indigo-700',
        className,
      )}
      {...props}
    />
  );
};
EOF
cat components/ui/badge/index.ts
